import fs from "node:fs";
import os from "node:os";
import path from "node:path";
import { browserCheckPlan, browserChecks, executeBrowserChecks, CheckCommandError, checkEnvironment } from "../scripts/check";
import { validateRelease } from "../scripts/release";
const root=path.resolve(import.meta.dir,"..");
const ledger=await Bun.file(path.join(root,"docs/verification/workflow-migration/ledger.json")).json();
const release=await validateRelease(path.join(root,".artifacts/release"));
const runtime=process.env.ACME_BROWSER_RUNTIME;
if(!runtime)throw new Error("Set ACME_BROWSER_RUNTIME");
const consumer=fs.mkdtempSync(path.join(os.tmpdir(),"acme-workflow-relocation-"));
const output=path.join(root,".artifacts/workflow-runtime");
fs.mkdirSync(output,{recursive:true});
const dependencies=Object.fromEntries(release.packages.map(pkg=>[pkg.name,"file:"+path.join(root,".artifacts/release/archives",pkg.filename)]));
await Bun.write(path.join(consumer,"package.json"),JSON.stringify({name:"workflow-relocation-consumer",private:true,type:"module",dependencies:{...dependencies,react:"19.3.0","react-dom":"19.3.0",lit:"3.3.3"}}));
const entries=browserChecks.map(entry=>({id:entry.id,file:ledger.records.find((record:any)=>record.source===entry.file)?.destinations[0].path??entry.file}));
const plan=browserCheckPlan(release,consumer,runtime,root,entries);
const fingerprints=Object.fromEntries(plan.map(entry=>[entry.file,new Bun.CryptoHasher("sha256").update(fs.readFileSync(entry.file)).digest("hex")]));
let server:Bun.Server<undefined>|undefined;
try{
  const install=Bun.spawn([process.execPath,"install","--ignore-scripts"],{cwd:consumer,env:checkEnvironment(),stdout:"inherit",stderr:"inherit"});
  if(await install.exited!==0)throw new Error("Fresh consumer install failed");
  const site=path.join(root,"_site");
  server=Bun.serve({hostname:"127.0.0.1",port:4180,async fetch(request){
    const relative=decodeURIComponent(new URL(request.url).pathname).replace(/^\//,"");
    const file=path.resolve(site,relative||"index.html");
    if(file!==site&&!file.startsWith(site+path.sep))return new Response("Invalid path",{status:400});
    const asset=Bun.file(file);if(await asset.exists())return new Response(asset);
    if(path.extname(relative))return new Response("Not found",{status:404});
    return new Response(Bun.file(path.join(site,"index.html")),{headers:{"Content-Type":"text/html"}});
  }});
  await Bun.write(path.join(output,"input.json"),JSON.stringify({date:new Date().toISOString(),runtime:Bun.version,release,consumer,entries,plan,fingerprints,scope:"Temporary relocation harness uses the unchanged shared invocation planner and executor. Only allocated file paths differ. Final activation still uses scripts/check.ts. Component JSON callers retain original equal bytes until task10."},null,2)+"\n");
  await executeBrowserChecks(plan,async check=>{
    const child=Bun.spawn([process.execPath,check.file,...check.args],{cwd:root,env:checkEnvironment(check.environment),stdout:"inherit",stderr:"inherit"});
    const status=await child.exited;if(status!==0)throw new CheckCommandError([check.file,...check.args],status);
  },async(results,complete)=>{
    await Bun.write(path.join(output,"browser.json.tmp"),JSON.stringify({date:new Date().toISOString(),version:release.version,planned:plan.length,completed:results.length,complete,results},null,2)+"\n");
    fs.renameSync(path.join(output,"browser.json.tmp"),path.join(output,"browser.json"));
  });
}finally{
  server?.stop(true);
  for(const file of new Bun.Glob("*{results,result}.json").scanSync(consumer))fs.copyFileSync(path.join(consumer,file),path.join(output,file));
  fs.rmSync(consumer,{recursive:true,force:true});
}

import fs from "node:fs";
import os from "node:os";
import path from "node:path";
import { checkEnvironment } from "../scripts/check";
import { validateRelease } from "../scripts/release";
const root=path.resolve(import.meta.dir,".."),output=path.join(root,".artifacts/workflow-runtime");
const release=await validateRelease(path.join(root,".artifacts/release"));
const core=release.packages.find(pkg=>pkg.name==="@acmelabs/design-system")!;
const runtime=process.env.ACME_BROWSER_RUNTIME;if(!runtime)throw new Error("Set ACME_BROWSER_RUNTIME");
const environment=checkEnvironment({ACME_BROWSER_RUNTIME:runtime,ACME_DOCS_URL:"http://127.0.0.1:4180",ACME_CORE_ARCHIVE:path.join(root,".artifacts/release/archives",core.filename),ACME_BUN_PATH:process.execPath});
const jobs=[
  ["08-documentation-action-labels.browser-check","scripts/verification/documentation/action-labels.browser-check.ts"],
  ["08-documentation-appearance.browser-check","scripts/verification/documentation/appearance.browser-check.ts"],
  ["08-documentation-table-source-isolation.browser-check","scripts/verification/documentation/table-source-isolation.browser-check.ts"],
  ["08-devtools-manual","scripts/verification/devtools/browser-check.ts"],
  ["08-workspace-consumer","scripts/verification/workspace/packed-consumer-check.ts"],
  ["08-workspace-install","scripts/verification/workspace/install-check.ts"],
];
const results:{id:string;file:string;passed:boolean;exitCode:number;sha256?:string;error?:string}[]=[];
const save=async(complete:boolean)=>Bun.write(path.join(output,"manual.json"),JSON.stringify({date:new Date().toISOString(),runtime:Bun.version,release,complete,results},null,2)+"\n");
const site=path.join(root,"_site");
const server=Bun.serve({hostname:"127.0.0.1",port:4180,async fetch(request){
  const relative=decodeURIComponent(new URL(request.url).pathname).replace(/^\//,"");
  const file=path.resolve(site,relative||"index.html");
  if(file!==site&&!file.startsWith(site+path.sep))return new Response("Invalid path",{status:400});
  if(await Bun.file(file).exists())return new Response(Bun.file(file));
  if(path.extname(relative))return new Response("Not found",{status:404});
  return new Response(Bun.file(path.join(site,"index.html")),{headers:{"Content-Type":"text/html"}});
}});
try{
  for(const [id,file] of jobs){
    console.log("BEGIN",id);
    const sha256=new Bun.CryptoHasher("sha256").update(fs.readFileSync(file)).digest("hex");
    const child=Bun.spawn([process.execPath,file],{cwd:root,env:environment,stdout:"inherit",stderr:"inherit"});
    const exitCode=await child.exited;
    results.push({id,file,passed:exitCode===0,exitCode,sha256});await save(false);
  }
  const consumer=fs.mkdtempSync(path.join(os.tmpdir(),"acme-workflow-public-types-"));
  try{
    const reactTypes=await Bun.file(path.join(root,"node_modules/@types/react/package.json")).json();
    const reactDOMTypes=await Bun.file(path.join(root,"node_modules/@types/react-dom/package.json")).json();
    const dependencies=Object.fromEntries(release.packages.filter(pkg=>["@acmelabs/design-system","@acmelabs/design-system-react"].includes(pkg.name)).map(pkg=>[pkg.name,"file:"+path.join(root,".artifacts/release/archives",pkg.filename)]));
    Object.assign(dependencies,{react:"19.3.0","react-dom":"19.3.0","@types/react":reactTypes.version,"@types/react-dom":reactDOMTypes.version});
    await Bun.write(path.join(consumer,"package.json"),JSON.stringify({name:"workflow-public-type-consumer",private:true,type:"module",dependencies}));
    fs.copyFileSync(path.join(root,"scripts/verification/react/fixtures/public-types.tsx"),path.join(consumer,"public-types.tsx"));
    const install=Bun.spawn([process.execPath,"install","--ignore-scripts"],{cwd:consumer,env:environment,stdout:"inherit",stderr:"inherit"});
    if(await install.exited!==0)throw new Error("Public type consumer install failed");
    const child=Bun.spawn([process.execPath,path.join(root,"node_modules/typescript/bin/tsc"),"--noEmit","--strict","--target","ES2022","--module","ESNext","--moduleResolution","bundler","--jsx","react-jsx","--skipLibCheck","--types","react","public-types.tsx"],{cwd:consumer,env:environment,stdout:"inherit",stderr:"inherit"});
    const exitCode=await child.exited;results.push({id:"08-react-types",file:"scripts/verification/react/fixtures/public-types.tsx",passed:exitCode===0,exitCode});
  }catch(error){results.push({id:"08-react-types",file:"scripts/verification/react/fixtures/public-types.tsx",passed:false,exitCode:1,error:String(error)});}
  finally{fs.rmSync(consumer,{recursive:true,force:true});}
}finally{server.stop(true);await save(true);}
if(results.length!==jobs.length+1||results.some(result=>!result.passed))process.exitCode=1;
